  if (typeof j.text === "string") return j.text;
  if (typeof j.output === "string") return j.output;
  if (typeof j.data === "string") return j.data;
  return JSON.stringify(j);
}
function safeParse(raw) {
  var s = String(raw).replace(/```json/gi, "").replace(/```/g, "").trim();
  var a = s.indexOf("{"); var b = s.lastIndexOf("}");
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
var state;
try { state = $("Retry Counter").last().json; } catch (e) { state = null; }
if (!state) state = $("Prepare Inputs").first().json;
var j = $input.first().json;
var parsed = (j && Array.isArray(j.posts)) ? j : safeParse(getText(j));
var posts = [];
var parse_error = "";
if (!parsed || !Array.isArray(parsed.posts)) {
  parse_error = "Invalid or missing JSON from Generate";
} else {
  var wanted = String(state.platforms).split(",").map(function (x) { return x.trim(); }).filter(Boolean);
  posts = parsed.posts.map(function (p) {
    var tags = p.hashtags;
    if (typeof tags === "string") tags = tags.split(/[\s,]+/).filter(Boolean);
    if (!Array.isArray(tags)) tags = [];
    return {
      platform: String(p.platform || "").trim(),
      caption: String(p.caption || ""),
      hashtags: tags.map(function (t) { return String(t).startsWith("#") ? String(t) : "#" + t; }),
      hook: String(p.hook || ""),
      cta: String(p.cta || ""),
      best_post_time: String(p.best_post_time || "")
    };
  }).filter(function (p) { return p.platform && p.caption; });
  if (wanted.length) posts = posts.filter(function (p) { return wanted.indexOf(p.platform) !== -1; });
  if (!posts.length) parse_error = "No valid posts for the selected platforms";
}
return [{ json: Object.assign({}, state, { posts: posts, parse_error: parse_error }) }];

