function getText(j) {
  if (j.content && j.content.parts) return j.content.parts.map(function (p) { return p.text || ""; }).join("");
  if (Array.isArray(j.candidates) && j.candidates[0] && j.candidates[0].content) return j.candidates[0].content.parts.map(function (p) { return p.text || ""; }).join("");
  if (typeof j.text === "string") return j.text;
  if (typeof j.output === "string") return j.output;
  if (typeof j.data === "string") return j.data;
  return JSON.stringify(j);
}
function safeParse(raw) {
  var s = String(raw).replace(/```json/gi, "").replace(/```/g, "").trim();
  var a = s.indexOf("{"); var b = s.lastIndexOf("}");
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
var state = $("Parse Generated Posts").last().json;
var j = $input.first().json;
var r = (j && typeof j.score !== "undefined") ? j : safeParse(getText(j));
var score = 0; var issues = []; var fix = "";
if (!r) {
  issues = ["Reviewer returned invalid JSON"];
  fix = "Re-check spoilers, platform length limits, tone and dialect consistency.";
} else {
  score = Number(r.score); if (isNaN(score)) score = 0;
  score = Math.max(0, Math.min(10, score));
  issues = Array.isArray(r.issues) ? r.issues : [String(r.issues || "")].filter(Boolean);
  fix = String(r.fix_instructions || "");
}
if (state.parse_error) { score = 0; issues.push(state.parse_error); }
var passed = score >= 7;
var retries = Number(state.retry_count) || 0;
var needs_retry = !passed && retries < 2;
var manual_edit = !passed && retries >= 2;
return [{ json: Object.assign({}, state, { score: score, issues: issues, approved_by_reviewer: passed, review_fix_instructions: fix, needs_retry: needs_retry, manual_edit: manual_edit }) }];

var s = $input.first().json;

function esc(t) {
  return String(t == null ? "" : t)
    .replace(/([_*`\[])/g, "\\$1")
    .replace(/[<>&]/g, " ");
}

var lines = [];

if (s.manual_edit) lines.push("NEEDS MANUAL EDIT - reviewer did not approve after 2 retries");
lines.push("Series: " + esc(s.series) + " | Episode " + esc(s.episode));
lines.push("Review score: " + s.score + "/10 | Retries: " + s.retry_count);
if (s.issues && s.issues.length) lines.push("Issues: " + esc(s.issues.join("; ")));
lines.push("");

(s.posts || []).forEach(function (p) {
  lines.push("[" + esc(p.platform) + "]");
  lines.push("Hook: " + esc(p.hook));
  lines.push(esc(p.caption));
  lines.push(esc((p.hashtags || []).join(" ")));
  lines.push("CTA: " + esc(p.cta) + " | Best time: " + esc(p.best_post_time));
  lines.push("");
});

var preview = lines.join("\n");
if (preview.length > 3500) {
  preview = preview.slice(0, 3500);
  var cut = preview.lastIndexOf("\n");
  if (cut > 0) preview = preview.slice(0, cut);
  preview += "\n...(truncated)";
}

return [{ json: Object.assign({}, s, { preview: preview }) }];

var s = $("Build Preview").first().json;
var date = new Date().toISOString().slice(0, 10);
var status = s.manual_edit ? "Approved - manual edit flagged" : "Approved";
return s.posts.map(function (p) {
  return { json: {
    date: date, series: s.series, episode: String(s.episode), platform: p.platform,
    caption: p.caption, hashtags: p.hashtags.join(" "), hook: p.hook, cta: p.cta,
    best_post_time: p.best_post_time, review_score: s.score, status: status
  } };
});

